<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"><title>New Employee - ERP</title><link rel="stylesheet" href="../../assets/css/style.css?v=<?= time() ?>"><style>* { margin: 0; padding: 0; box-sizing: border-box; } body { background: #f5f5f5; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif; } .header { background: #fff; border-bottom: 1px solid #e0e0e0; padding: 16px 24px; display: flex; justify-content: space-between; align-items: center; } .header h1 { font-size: 1.5rem; font-weight: 500; } .container { max-width: 800px; margin: 24px auto; padding: 0 24px; } .card { background: white; border-radius: 8px; border: 1px solid #e0e0e0; overflow: hidden; } .card-body { padding: 24px; } .form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; } .form-group { margin-bottom: 16px; } .form-group.full-width { grid-column: span 2; } label { display: block; margin-bottom: 8px; font-weight: 500; color: #202124; font-size: 0.875rem; } input, select, textarea { width: 100%; padding: 10px 12px; border: 1px solid #dadce0; border-radius: 4px; font-size: 0.875rem; } .btn { padding: 10px 24px; border-radius: 4px; text-decoration: none; font-size: 0.875rem; font-weight: 500; cursor: pointer; border: none; } .btn-primary { background: #1a73e8; color: white; } .btn-secondary { background: #fff; color: #202124; border: 1px solid #dadce0; } .alert { padding: 12px 16px; border-radius: 4px; margin-bottom: 20px; display: none; } .alert-success { background: #e6f4ea; color: #137333; } .alert-error { background: #fce8e6; color: #c5221f; } .section-title { grid-column: span 2; font-size: 1.1rem; font-weight: 600; margin: 20px 0 10px 0; border-bottom: 1px solid #f1f3f4; padding-bottom: 8px; color: #1a73e8; }</style></head>
<body><div class="header"><h1>New Employee</h1><a href="employees.php" class="btn btn-secondary">Cancel</a></div><div class="container"><div class="card"><div class="card-body"><div id="alertMessage" class="alert"></div><form id="createEmployeeForm"><div class="form-grid"><div class="section-title" style="margin-top: 0;">Personal Details</div><div class="form-group"><label>First Name *</label><input type="text" name="first_name" required></div><div class="form-group"><label>Last Name *</label><input type="text" name="last_name" required></div><div class="form-group"><label>Email</label><input type="email" name="email"></div><div class="form-group"><label>Phone</label><input type="text" name="phone"></div><div class="section-title">Employment Details</div><div class="form-group"><label>Department</label><select name="department_id"><option value="">Select Department</option><?php foreach ($departments as $d): ?><option value="<?= $d['id'] ?>"><?= htmlspecialchars($d['name']) ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Position</label><input type="text" name="position" placeholder="e.g. Sales Manager"></div><div class="form-group"><label>Join Date *</label><input type="date" name="join_date" value="<?= date('Y-m-d') ?>" required></div><div class="form-group"><label>Status</label><select name="status"><option value="active">Active</option><option value="on_leave">On Leave</option><option value="terminated">Terminated</option><option value="resigned">Resigned</option></select></div><div class="section-title">Financial Details</div><div class="form-group"><label>Basic Salary (Monthly) *</label><input type="number" name="basic_salary" step="0.01" required placeholder="0.00"></div><div class="form-group"><label>Bank Name</label><input type="text" name="bank_name"></div><div class="form-group full-width"><label>Bank Account Number</label><input type="text" name="bank_account_number"></div></div><div style="margin-top: 24px; text-align: right;"><button type="submit" class="btn btn-primary">Save Employee</button></div></form></div></div></div><script>document.getElementById('createEmployeeForm').addEventListener('submit', async function(e) { e.preventDefault(); const btn = this.querySelector('button[type="submit"]'); btn.disabled = true; btn.textContent = 'Saving...'; const alert = document.getElementById('alertMessage'); alert.style.display = 'none'; try { const formData = new FormData(this); formData.append('action', 'create'); const response = await fetch('../api/employees.php', { method: 'POST', body: formData }); const result = await response.json(); if (result.success) { alert.className = 'alert alert-success'; alert.textContent = 'Employee created successfully! Redirecting...'; alert.style.display = 'block'; setTimeout(() => window.location.href = 'employees.php', 1500); } else { throw new Error(result.message || 'Failed to create employee'); } } catch (error) { alert.className = 'alert alert-error'; alert.textContent = error.message; alert.style.display = 'block'; btn.disabled = false; btn.textContent = 'Save Employee'; } });</script></body>
</html>

